<template><div class="orders-page"><div class="heading"><div><div class="eyebrow">QINGHE CAMPUS / ORDERS</div><h1>订单工作台</h1><p>从接单到送达，照顾好每一份期待。每15秒自动刷新。</p></div><el-button @click="load">刷新订单</el-button></div><el-card shadow="never"><el-tabs v-model="status" @tab-change="changeStatus"><el-tab-pane label="全部订单" name=""/><el-tab-pane v-for="(label,key) in statuses" :key="key" :label="label" :name="key"/></el-tabs><el-table v-loading="loading" :data="rows"><el-table-column label="订单编号" min-width="200"><template #default="{row}"><el-link type="primary" @click="detail(row)">{{row.id.slice(0,16)}}…</el-link><div class="sub">{{row.created_at}}</div></template></el-table-column><el-table-column label="商家" prop="store_name" min-width="130"/><el-table-column label="配送方式" width="110"><template #default="{row}">{{row.type==='DELIVERY'?'外卖配送':'到店自取'}}</template></el-table-column><el-table-column label="金额" width="100"><template #default="{row}">¥{{money(row.total)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='COMPLETED'?'success':row.status==='CANCELLED'?'info':'warning'">{{statuses[row.status]}}</el-tag></template></el-table-column><el-table-column label="收货信息 / 取餐码" min-width="200"><template #default="{row}">{{row.type==='PICKUP'?row.pickup_code:row.address}}</template></el-table-column><el-table-column label="操作" width="165" fixed="right"><template #default="{row}"><el-button v-if="next(row)" link type="primary" :disabled="busy" @click="advance(row)">{{next(row).label}}</el-button><el-button link @click="detail(row)">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load" style="margin-top:24px;justify-content:flex-end"/></el-card>
<el-drawer v-model="visible" title="订单详情" size="520px"><template v-if="order.id"><el-descriptions :column="1" border><el-descriptions-item label="订单编号">{{order.id}}</el-descriptions-item><el-descriptions-item label="商家">{{order.store_name}}</el-descriptions-item><el-descriptions-item label="状态">{{statuses[order.status]}}</el-descriptions-item><el-descriptions-item label="收货信息">{{order.address}}</el-descriptions-item><el-descriptions-item label="取餐码">{{order.pickup_code}}</el-descriptions-item><el-descriptions-item label="备注">{{order.remark||'无'}}</el-descriptions-item></el-descriptions><el-table :data="order.items" style="margin:25px 0"><el-table-column label="商品" prop="name"/><el-table-column label="数量" prop="quantity" width="70"/><el-table-column label="单价" width="90"><template #default="{row}">¥{{money(row.price)}}</template></el-table-column></el-table><p>配送费 ¥{{money(order.delivery_fee)}} / 优惠 ¥{{money(order.discount)}}</p><h3>实付 ¥{{money(order.total)}}</h3><el-button v-if="next(order)" type="primary" :disabled="busy" @click="advance(order)">{{next(order).label}}</el-button></template></el-drawer></div></template>
<script setup>
import {ref,watch,onMounted,onBeforeUnmount} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {foodGet,foodPost,money,statuses} from '@/api/food';const route=useRoute(),router=useRouter();const rows=ref([]),status=ref(statuses[route.query.status]?route.query.status:''),page=ref(1),total=ref(0),loading=ref(false),busy=ref(false),visible=ref(false),order=ref({});function changeStatus(){page.value=1;if((route.query.status||'')!==status.value){router.replace({query:{...route.query,status:status.value||undefined}});load()}}
watch(()=>route.query.status,v=>{if(route.path!='/food/orders')return;const next=statuses[v]?v:'';if(next===status.value)return;status.value=next;page.value=1;load()});let timer,revision=0;
async function load(){const ticket=++revision;loading.value=true;try{const r=await foodGet('/orders',{page:page.value,status:status.value});if(ticket===revision){rows.value=r.data.rows;total.value=r.data.total}}finally{if(ticket===revision)loading.value=false}}function next(row){return {UNPAID:{status:'CANCELLED',label:'取消未支付单'},PENDING:{status:'PREPARING',label:'接单并制作'},PREPARING:{status:row.type==='PICKUP'?'READY':'DELIVERING',label:row.type==='PICKUP'?'通知取餐':'开始配送'},READY:{status:'COMPLETED',label:'确认已取餐'},DELIVERING:{status:'COMPLETED',label:'确认送达'}}[row.status]}async function detail(row){order.value=(await foodGet('/orders/'+row.id)).data;visible.value=true}async function advance(row){const action=next(row);await ElMessageBox.confirm('确认'+action.label+'？','更新订单状态');busy.value=true;try{await foodPost('/orders/'+row.id+'/status',{status:action.status});ElMessage.success('状态已更新');await load();if(visible.value)await detail(row)}finally{busy.value=false}}onMounted(()=>{load();timer=setInterval(()=>{if(!loading.value)load()},15000)});onBeforeUnmount(()=>{revision++;clearInterval(timer)});
</script><style scoped>.orders-page{padding:32px;background:#f6f8f3;min-height:calc(100vh - 85px)}.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:25px}.eyebrow{font-size:11px;letter-spacing:2px;color:#93a186}h1{font-size:27px;color:#35533c;margin:12px 0}p{font-size:13px;color:#96a08d}.sub{font-size:11px;color:#9aa590;margin-top:8px}.el-card{border-radius:15px;border-color:#e6eddf}</style>
